-- ── Bibliothèque d'ouvrages : référentiels et articles ───────────────────────
-- La page « Cahier des charges » devient la bibliothèque des articles
-- réutilisables dans les CCTP, DPGF et DQE. Cette migration pose les trois
-- référentiels sur lesquels un article se classe, étend `articles_type` pour
-- les porter, et ouvre l'historique de prix.
--
-- Les tables `ref_*` sont GLOBALES, pas multi-tenant : ce sont des
-- nomenclatures publiques (EU SfB plus, NF DTU/BNTEC, NAF INSEE), identiques
-- pour tous les cabinets. Elles portent tout de même une RLS en lecture seule
-- pour les utilisateurs authentifiés — le backend écrit avec la service role,
-- qui la contourne. Les dupliquer par tenant n'apporterait rien et
-- multiplierait par le nombre de cabinets une donnée qui ne change qu'à
-- chaque révision de la norme.
--
-- Sources exactes des données injectées plus bas :
--   - EU SfB plus, août 2024 (classification des éléments d'ouvrage)
--   - NF DTU pour les métiers du Bâtiment, BNTEC/FFB, janvier 2026
--   - Nomenclature d'activités française NAF rév. 2, INSEE (section F et
--     activités connexes du bâtiment)

-- ── Référentiel 1 : éléments d'ouvrage (EU SfB plus) ────────────────────────
CREATE TABLE IF NOT EXISTS ref_sfb_elements (
  code        TEXT PRIMARY KEY,
  parent_code TEXT REFERENCES ref_sfb_elements(code) ON DELETE CASCADE,
  niveau      SMALLINT NOT NULL CHECK (niveau IN (1, 2)),
  libelle     TEXT NOT NULL,
  libelle_en  TEXT,
  position    INT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_ref_sfb_parent ON ref_sfb_elements(parent_code);

-- ── Référentiel 2 : corps d'état (nomenclature FFB) et NF DTU ───────────────
CREATE TABLE IF NOT EXISTS ref_corps_etat (
  code     TEXT PRIMARY KEY,
  famille  TEXT NOT NULL,
  libelle  TEXT NOT NULL,
  position INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS ref_dtu (
  code       TEXT PRIMARY KEY,          -- « NF DTU 13.1 »
  prefixe    TEXT NOT NULL,             -- NF DTU | XP DTU | FD DTU
  numero     TEXT NOT NULL,             -- « 13.1 »
  titre      TEXT NOT NULL,
  norme      TEXT,                      -- référence AFNOR, « P11-201 »
  amendement BOOLEAN NOT NULL DEFAULT FALSE
);

-- Un même DTU relève parfois de deux métiers (NF DTU 26.1 : façades ET
-- enduits intérieurs), d'où une liaison N-N plutôt qu'une colonne.
CREATE TABLE IF NOT EXISTS ref_dtu_corps_etat (
  dtu_code        TEXT NOT NULL REFERENCES ref_dtu(code) ON DELETE CASCADE,
  corps_etat_code TEXT NOT NULL REFERENCES ref_corps_etat(code) ON DELETE CASCADE,
  PRIMARY KEY (dtu_code, corps_etat_code)
);
CREATE INDEX IF NOT EXISTS idx_ref_dtu_corps_etat_corps ON ref_dtu_corps_etat(corps_etat_code);

-- ── Référentiel 3 : codes NAF (INSEE) ───────────────────────────────────────
CREATE TABLE IF NOT EXISTS ref_naf (
  code        TEXT PRIMARY KEY,
  parent_code TEXT,
  niveau      SMALLINT NOT NULL,   -- 2 division, 3 groupe, 4 classe, 5 sous-classe
  libelle     TEXT NOT NULL,
  section     TEXT
);
CREATE INDEX IF NOT EXISTS idx_ref_naf_parent ON ref_naf(parent_code);

-- Lecture ouverte à tout utilisateur authentifié, écriture réservée à la
-- service role (qui contourne la RLS) : une nomenclature ne se modifie pas
-- depuis l'application.
ALTER TABLE ref_sfb_elements   ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_corps_etat     ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_dtu            ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_dtu_corps_etat ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_naf            ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['ref_sfb_elements', 'ref_corps_etat', 'ref_dtu',
                           'ref_dtu_corps_etat', 'ref_naf'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS "read_all_authenticated" ON %I', t);
    EXECUTE format('CREATE POLICY "read_all_authenticated" ON %I FOR SELECT USING (auth.role() = ''authenticated'')', t);
  END LOOP;
END;
$$;

-- ── Articles : classement, provenance, traçabilité ──────────────────────────
-- `articles_type` portait déjà designation/unite/prix_unitaire/categorie/
-- lot_type (migrate_add_bpu.sql). S'y ajoutent le classement sur les trois
-- référentiels et la provenance.
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS sfb_code        TEXT REFERENCES ref_sfb_elements(code) ON DELETE SET NULL;
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS dtu_code        TEXT REFERENCES ref_dtu(code)          ON DELETE SET NULL;
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS corps_etat_code TEXT REFERENCES ref_corps_etat(code)   ON DELETE SET NULL;
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS naf_code        TEXT REFERENCES ref_naf(code)          ON DELETE SET NULL;

-- `origine` est le repère demandé : il distingue un article du fonds de
-- référence d'un article créé par le cabinet, et sert à le signaler comme tel
-- dans les CCTP et DPGF. `source` (déjà là) garde le détail libre
-- (« projet:<id> »), cette colonne-ci porte le vocabulaire fermé.
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS origine TEXT NOT NULL DEFAULT 'saisie';
ALTER TABLE articles_type DROP CONSTRAINT IF EXISTS articles_type_origine_check;
ALTER TABLE articles_type ADD CONSTRAINT articles_type_origine_check
  CHECK (origine IN ('reference', 'saisie', 'bpu', 'offre', 'import'));

ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS created_by TEXT;
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
ALTER TABLE articles_type ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

CREATE INDEX IF NOT EXISTS idx_articles_type_sfb        ON articles_type(tenant_id, sfb_code);
CREATE INDEX IF NOT EXISTS idx_articles_type_dtu        ON articles_type(tenant_id, dtu_code);
CREATE INDEX IF NOT EXISTS idx_articles_type_corps_etat ON articles_type(tenant_id, corps_etat_code);
CREATE INDEX IF NOT EXISTS idx_articles_type_origine    ON articles_type(tenant_id, origine);

-- ── Historique de prix ──────────────────────────────────────────────────────
-- `articles_type.prix_unitaire` reste le prix courant, celui qu'on injecte
-- dans un DPGF. Cette table garde chaque prix OBSERVÉ, sans l'écraser : c'est
-- elle qui permettra d'enrichir la bibliothèque avec les réponses des
-- entreprises aux appels d'offres et de lire une fourchette plutôt qu'un
-- chiffre unique.
CREATE TABLE IF NOT EXISTS article_prix_observations (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  article_id       TEXT NOT NULL REFERENCES articles_type(id) ON DELETE CASCADE,
  prix_ht          NUMERIC NOT NULL,
  unite            TEXT,
  date_observation DATE NOT NULL DEFAULT CURRENT_DATE,
  origine          TEXT NOT NULL DEFAULT 'saisie'
                   CHECK (origine IN ('saisie', 'bpu', 'offre', 'marche', 'import')),
  entreprise       TEXT,     -- l'entreprise dont émane le prix, pour une offre
  project_id       TEXT,
  tender_id        TEXT,
  notes            TEXT,
  created_by       TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_prix_obs_article ON article_prix_observations(tenant_id, article_id, date_observation DESC);
CREATE INDEX IF NOT EXISTS idx_prix_obs_tenant  ON article_prix_observations(tenant_id);

ALTER TABLE article_prix_observations ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON article_prix_observations;
CREATE POLICY "tenant_isolation" ON article_prix_observations
  FOR ALL USING (tenant_id = my_tenant_id());

-- Synchronisation cloud <-> local, comme migrate_add_bpu.sql l'a fait pour
-- bpu_data. server/syncTables.ts doit lister 'article_prix_observations' en
-- regard, et le littéral ARRAY[...] de migrate_add_sync_infra.sql aussi.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'touch_updated_at') THEN
    EXECUTE 'DROP TRIGGER IF EXISTS trg_touch_updated_at ON articles_type';
    EXECUTE 'CREATE TRIGGER trg_touch_updated_at BEFORE UPDATE ON articles_type '
         || 'FOR EACH ROW EXECUTE FUNCTION touch_updated_at()';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'log_sync_change') THEN
    EXECUTE 'DROP TRIGGER IF EXISTS trg_log_sync_change ON article_prix_observations';
    EXECUTE 'CREATE TRIGGER trg_log_sync_change AFTER INSERT OR UPDATE OR DELETE ON article_prix_observations '
         || 'FOR EACH ROW EXECUTE FUNCTION log_sync_change()';
  END IF;
END;
$$;


-- ── Données de référence ────────────────────────────────────────────────────
-- EU SfB plus (août 2024) : 32 éléments, 284 sous-éléments.
ON CONFLICT (code) DO UPDATE SET parent_code = EXCLUDED.parent_code, niveau = EXCLUDED.niveau, libelle = EXCLUDED.libelle, libelle_en = EXCLUDED.libelle_en, position = EXCLUDED.position;

-- Corps d'état de la nomenclature FFB : 23 métiers en 4 familles.
ON CONFLICT (code) DO UPDATE SET famille = EXCLUDED.famille, libelle = EXCLUDED.libelle, position = EXCLUDED.position;

-- NF DTU (BNTEC/FFB, janvier 2026) : 115 normes.
ON CONFLICT (code) DO UPDATE SET prefixe = EXCLUDED.prefixe, numero = EXCLUDED.numero, titre = EXCLUDED.titre, norme = EXCLUDED.norme, amendement = EXCLUDED.amendement;

-- Rattachement DTU / corps d'état : 121 liens.
ON CONFLICT DO NOTHING;

-- NAF rév. 2 (INSEE), section F et activités connexes : 141 codes.
ON CONFLICT (code) DO UPDATE SET parent_code = EXCLUDED.parent_code, niveau = EXCLUDED.niveau, libelle = EXCLUDED.libelle, section = EXCLUDED.section;
